  name: string;
  color: LabelColor;
}

export interface Draft {
  id: string;
  threadId: string | null;
  mode: ComposeMode;
  to: Address[];
  cc: Address[];
  bcc: Address[];
  subject: string;
  html: string;
  attachments: Attachment[];
  updatedAt: number;
  /** True for a brand-new compose that the user has not typed into yet. */
  pristine?: boolean;
}

/**
 * undo: waiting for the undo-send window to close
 * scheduled: user-chosen send time
 * queued: sent while offline, flushed on reconnect
 */
export type OutgoingKind = 'undo' | 'scheduled' | 'queued';

export interface Outgoing {
  id: string;
  kind: OutgoingKind;
  sendAt: number;
  createdAt: number;
  draft: Draft;
}

export interface Settings {
  signature: string;
  theme: 'light' | 'dark' | 'system';
  density: 'comfortable' | 'cozy' | 'compact';
  readingPane: boolean;
  undoSendSeconds: 5 | 10 | 30;
  categories: boolean;
  offline: boolean;
  incomingMail: boolean;
}

export interface MailData {
  account: Address;
  threads: Thread[];
  labels: Label[];
  drafts: Draft[];
  outgoing: Outgoing[];
  settings: Settings;
  recentSearches: string[];
  nextIncomingAt: number;
}

