/** A new message that arrives while the app is open (simulated inbound mail). */
export function createIncomingThread(now: number): Thread {
  const tpl = INCOMING[Math.floor(Math.random() * INCOMING.length)];
  const messageId = uid('msg');
  const thread = toThread({
    key: uid('incoming'),
    subject: tpl.subject,
    category: tpl.category,
    labels: tpl.labels ?? [],
    msgs: [{ from: tpl.from, at: now, unread: true, html: tpl.html, attach: tpl.attach }],
  });
  return { ...thread, messages: [toMessage({ from: tpl.from, at: now, unread: true, html: tpl.html, attach: tpl.attach }, messageId)] };
}

