              onMouseEnter={() => setActive(i)}
              className={cn(
                'flex cursor-pointer items-center gap-3 px-4 py-2 text-sm',
                i === active ? 'bg-hover' : '',
              )}
            >
              {s.icon === 'user' && s.detail ? (
                <Avatar name={s.label.replace(/^(from|to): /, '')} email={s.detail} size={24} />
              ) : s.icon === 'clock' ? (
                <Clock className="size-4 text-ink-3" />
              ) : s.icon === 'user' ? (
                <User className="size-4 text-ink-3" />
              ) : s.icon === 'op' ? (
                <span className="flex size-4 items-center justify-center font-mono text-xs text-ink-3">:</span>
