import { Archive, Check, Clock, Mail, MailOpen, Paperclip, Star, Trash } from 'lucide-react';
import type { Label, Settings, Thread } from '../../domain/types';
import { isUnread, lastMessage, senderLine } from '../../domain/threads';
import { cn } from '../../lib/cn';
import { snippetOf } from '../../lib/text';
import { formatListDate } from '../../lib/time';
import * as commands from '../../store/commands';
import { useUI } from '../../store/uiStore';
import { Avatar, IconButton } from '../ui/primitives';
import { LABEL_CHIP } from '../labelStyles';
import { Highlight } from './Highlight';

interface ThreadRowProps {
  thread: Thread;
  me: string;
  layout: 'row' | 'stacked';
  density: Settings['density'];
  selected: boolean;
  focused: boolean;
  labels: Label[];
  hasDraft: boolean;
  terms: string[];
  now: number;
  onOpen: (threadId: string) => void;
}

const DENSITY_ROW: Record<Settings['density'], string> = {
  comfortable: 'min-h-[48px] py-2 text-sm',
  cozy: 'min-h-[40px] py-1.5 text-sm',
  compact: 'min-h-[32px] py-1 text-[13px]',
};

const DENSITY_STACK: Record<Settings['density'], string> = {
  comfortable: 'py-3',
  cozy: 'py-2.5',
  compact: 'py-2',
};

export function ThreadRow({
  thread,
  me,
  layout,
  density,
  selected,
  focused,
  labels,
  hasDraft,
  terms,
  now,
  onOpen,
}: ThreadRowProps) {
  const last = lastMessage(thread);
  const unread = isUnread(thread);
  const hasFiles = thread.messages.some((m) => m.attachments.length > 0);
  const sender = senderLine(thread, me);
  const snippet = snippetOf(last.text, 160);
  const date = formatListDate(last.date, now);
  const chips = thread.labelIds
    .map((id) => labels.find((l) => l.id === id))
    .filter((l): l is Label => Boolean(l))
    .slice(0, 2);
  const avatarSource =
    last.from.email === me ? (thread.messages.find((m) => m.from.email !== me)?.from ?? last.from) : last.from;

  const base = cn(
    'group relative flex cursor-pointer border-b border-line/70 px-3 transition-shadow',
    selected ? 'bg-selected' : 'bg-surface hover:shadow-[0_1px_2px_rgba(60,64,67,.25),0_1px_3px_rgba(60,64,67,.12)] hover:z-10',
    focused && 'ring-2 ring-inset ring-primary/60',
    unread ? 'text-ink' : 'text-ink-2',
  );

  const toggleStar = (e: React.MouseEvent) => {
    e.stopPropagation();
    commands.toggleStar([thread.id]);
  };

  const starButton = (
    <button
      type="button"
      onClick={toggleStar}
      aria-label={thread.starred ? 'Unstar conversation' : 'Star conversation'}
      className="shrink-0 rounded-full p-1 hover:bg-hover"
    >
      <Star
        className={cn(
          'size-[18px]',
          thread.starred ? 'fill-[#f4b400] text-[#f4b400]' : 'text-ink-3 opacity-60 group-hover:opacity-100',
        )}
      />
    </button>
  );

  if (layout === 'stacked') {
    return (
      <div
        id={`row-${thread.id}`}
        role="row"
        aria-selected={selected}
        onClick={() => onOpen(thread.id)}
        className={cn(base, 'items-start gap-3', DENSITY_STACK[density], unread && 'font-medium')}
      >
        <button
          type="button"
          aria-label={selected ? 'Deselect conversation' : 'Select conversation'}
          onClick={(e) => {
            e.stopPropagation();
            useUI.getState().toggleSelected(thread.id);
          }}
          className="relative mt-0.5 shrink-0 rounded-full"
        >
          {selected ? (
            <span className="flex size-10 items-center justify-center rounded-full bg-primary text-on-primary">
              <Check className="size-5" />
            </span>
          ) : (
            <Avatar name={avatarSource.name} email={avatarSource.email} size={40} />
          )}
        </button>
        <div className="min-w-0 flex-1">
          <div className="flex items-baseline gap-2">
            <span className={cn('truncate', unread ? 'font-semibold text-ink' : 'text-ink')}>{sender}</span>
            <span className={cn('ml-auto shrink-0 text-xs', unread ? 'font-semibold text-primary' : 'text-ink-3')}>
              {date}
            </span>
          </div>
          <div className="flex min-w-0 items-center gap-2">
            {hasDraft && <span className="shrink-0 text-xs font-semibold text-danger">Draft</span>}
            <span className={cn('truncate', unread ? 'font-semibold text-ink' : 'text-ink')}>
              <Highlight text={thread.subject} terms={terms} />
            </span>
            {hasFiles && <Paperclip className="size-3.5 shrink-0 text-ink-3" />}
          </div>
          <div className="truncate text-ink-3">
            <Highlight text={snippet} terms={terms} />
          </div>
        </div>
        {starButton}
      </div>
    );
  }

  return (
    <div
      id={`row-${thread.id}`}
      role="row"
      aria-selected={selected}
      onClick={() => onOpen(thread.id)}
      className={cn(base, 'items-center gap-2', DENSITY_ROW[density], unread && 'font-semibold')}
    >
      <input
        type="checkbox"
        className="size-4 shrink-0 cursor-pointer accent-primary"
        checked={selected}
        aria-label={`Select ${thread.subject}`}
        onClick={(e) => e.stopPropagation()}
        onChange={() => useUI.getState().toggleSelected(thread.id)}
      />
      {starButton}
      <span className={cn('w-[176px] shrink-0 truncate', unread ? 'text-ink' : 'text-ink-2')}>
        {sender}
      </span>
      <span className="flex min-w-0 flex-1 items-center gap-2">
        {hasDraft && <span className="shrink-0 text-danger">Draft</span>}
        {thread.important && <span className="size-1.5 shrink-0 rounded-full bg-[#f4b400]" title="Important" />}
        {chips.map((l) => (
          <span
            key={l.id}
            className={cn('shrink-0 rounded px-1.5 text-[11px] font-medium leading-4 font-normal', LABEL_CHIP[l.color])}
          >
            {l.name}
          </span>
        ))}
        <span className={cn('truncate', unread ? 'text-ink' : 'text-ink')}>
          <Highlight text={thread.subject} terms={terms} />
        </span>
        <span className="min-w-0 truncate font-normal text-ink-3">
          <Highlight text={` – ${snippet}`} terms={terms} />
        </span>
      </span>
      {hasFiles && <Paperclip className="size-4 shrink-0 text-ink-3" />}
      <span className={cn('w-[64px] shrink-0 whitespace-nowrap pr-1 text-right text-xs', unread ? 'text-ink' : 'text-ink-3')}>
        {date}
      </span>

      <div className="absolute right-2 top-1/2 hidden -translate-y-1/2 items-center gap-0.5 rounded-full bg-surface px-1 shadow-md group-hover:flex">
        <RowAction label="Archive" onClick={(e) => { stop(e); commands.archiveThreads([thread.id]); }}>
          <Archive className="size-4" />
        </RowAction>
        <RowAction label="Delete" onClick={(e) => { stop(e); commands.trashThreads([thread.id]); }}>
          <Trash className="size-4" />
        </RowAction>
        <RowAction
          label={isUnread(thread) ? 'Mark as read' : 'Mark as unread'}
          onClick={(e) => {
            stop(e);
            commands.toggleReadState([thread.id]);
          }}
        >
          {isUnread(thread) ? <MailOpen className="size-4" /> : <Mail className="size-4" />}
        </RowAction>
        <RowAction
          label="Snooze"
          onClick={(e) => {
            stop(e);
            const rect = e.currentTarget.getBoundingClientRect();
            commands.openMenu({ kind: 'snooze', ids: [thread.id], x: rect.left - 120, y: rect.bottom });
          }}
        >
          <Clock className="size-4" />
        </RowAction>
      </div>
    </div>
  );
}

function stop(e: React.MouseEvent) {
  e.stopPropagation();
}

function RowAction({ label, onClick, children }: { label: string; onClick: (e: React.MouseEvent<HTMLButtonElement>) => void; children: React.ReactNode }) {
  return (
    <IconButton label={label} onClick={onClick} className="size-8">
      {children}
    </IconButton>
  );
}

args.streamContent:
import type { MouseEvent, ReactNode } from 'react';
import { Archive, ChevronDown, ChevronLeft, ChevronRight, Clock, Inbox, Mail, MailOpen, OctagonAlert, RefreshCw, Tag, Trash, Ellipsis } from 'lucide-react';
import { isUnread } from '../../domain/threads';
import type { Folder } from '../../domain/types';
import { cn } from '../../lib/cn';
import * as actions from '../../store/actions';
import * as commands from '../../store/commands';
import { useMail } from '../../store/mailStore';
import { useUI } from '../../store/uiStore';
import { Dropdown, IconButton, MenuItem } from '../ui/primitives';
import { Button } from '../ui/Button';

interface ListToolbarProps {
  folder: Folder | null;
  visibleIds: string[];
  total: number;
  from: number;
  to: number;
  page: number;
  pageCount: number;
  onPage: (page: number) => void;
  onRefresh: () => void;
  refreshing: boolean;
}

export function ListToolbar({
  folder,
  visibleIds,
  total,
  from,
  to,
  page,
  pageCount,
  onPage,
  onRefresh,
  refreshing,
}: ListToolbarProps) {
  const selected = useUI((s) => s.selected);
  const setSelected = useUI((s) => s.setSelected);
  const ask = useUI((s) => s.ask);
  const threads = useMail((s) => s.data.threads);

  const selectedThreads = threads.filter((t) => selected.includes(t.id));
  const hasSelection = selected.length > 0;
  const allChecked = visibleIds.length > 0 && visibleIds.every((id) => selected.includes(id));
  const someChecked = hasSelection && !allChecked;
  const anyUnread = selectedThreads.some(isUnread);
  const inTrash = folder === 'trash';
  const inSpam = folder === 'spam';

  const pick = (predicate: (id: string) => boolean) => setSelected(visibleIds.filter(predicate));

  const emptyFolder = () => {
    const ids = threads.filter((t) => t.location === (inTrash ? 'trash' : 'spam')).map((t) => t.id);
    ask({
      title: inTrash ? 'Empty Trash now?' : 'Delete all spam messages?',
      body: `${ids.length} conversations will be deleted forever. This can't be undone.`,
      confirmLabel: inTrash ? 'Empty Trash' : 'Delete all',
      danger: true,
      onConfirm: () => {
        actions.removeThreads(ids);
        useUI.getState().setSelected([]);
      },
    });
  };

  const openMenuFrom = (kind: 'snooze' | 'labels') => (e: MouseEvent<HTMLButtonElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    commands.openMenu({ kind, ids: selected, x: rect.left, y: rect.bottom });
  };

  return (
    <div className="flex h-12 shrink-0 items-center gap-0.5 border-b border-line px-2 md:px-3">
      <Dropdown
        trigger={({ toggle }) => (
          <div className="flex items-center">
            <label className="flex size-9 cursor-pointer items-center justify-center rounded-full hover:bg-hover">
              <input
                type="checkbox"
                aria-label="Select all visible"
                className="size-4 cursor-pointer accent-primary"
                checked={allChecked}
                ref={(el) => {
                  if (el) el.indeterminate = someChecked;
                }}
                onChange={() => setSelected(allChecked ? [] : visibleIds)}
              />
            </label>
            <IconButton label="Selection options" onClick={toggle} className="size-6">
              <ChevronDown className="size-4" />
            </IconButton>
          </div>
        )}
      >
        {(close) => (
          <>
            <MenuItem onSelect={() => { setSelected(visibleIds); close(); }}>All</MenuItem>
            <MenuItem onSelect={() => { setSelected([]); close(); }}>None</MenuItem>
            <MenuItem onSelect={() => { pick((id) => !threads.find((t) => t.id === id && isUnread(t))); close(); }}>Read</MenuItem>
            <MenuItem onSelect={() => { pick((id) => !!threads.find((t) => t.id === id && isUnread(t))); close(); }}>Unread</MenuItem>
            <MenuItem onSelect={() => { pick((id) => !!threads.find((t) => t.id === id && t.starred)); close(); }}>Starred</MenuItem>
            <MenuItem onSelect={() => { pick((id) => !threads.find((t) => t.id === id && t.starred)); close(); }}>Unstarred</MenuItem>
          </>
        )}
      </Dropdown>

      <IconButton label="Refresh" onClick={onRefresh} className="hidden sm:inline-flex">
        <RefreshCw className={cn('size-[18px]', refreshing && 'animate-spin')} />
      </IconButton>

      <div className="mx-1 hidden h-5 w-px bg-line sm:block" />

      <ActionButton label="Archive" disabled={!hasSelection} onClick={() => commands.archiveThreads(selected)}>
        <Archive className="size-[18px]" />
      </ActionButton>
      {!inSpam && !inTrash && (
        <ActionButton label="Report spam" disabled={!hasSelection} onClick={() => commands.reportSpam(selected)} className="hidden sm:inline-flex">
          <OctagonAlert className="size-[18px]" />
        </ActionButton>
      )}
      <ActionButton
        label={inTrash ? 'Delete forever' : 'Delete'}
        disabled={!hasSelection}
        onClick={() => {
          if (inTrash) {
            ask({
              title: 'Delete forever?',
              body: `${selected.length} conversation(s) will be deleted permanently.`,
              confirmLabel: 'Delete forever',
              danger: true,
              onConfirm: () => commands.deleteForever(selected),
            });
          } else {
            commands.trashThreads(selected);
          }
        }}
      >
        <Trash className="size-[18px]" />
      </ActionButton>
      <ActionButton
        label={anyUnread ? 'Mark as read' : 'Mark as unread'}
        disabled={!hasSelection}
        onClick={() => commands.toggleReadState(selected)}
        className="hidden sm:inline-flex"
      >
        {anyUnread ? <MailOpen className="size-[18px]" /> : <Mail className="size-[18px]" />}
      </ActionButton>
      <ActionButton label="Snooze" disabled={!hasSelection} onClick={openMenuFrom('snooze')}>
        <Clock className="size-[18px]" />
      </ActionButton>
      <ActionButton label="Labels" disabled={!hasSelection} onClick={openMenuFrom('labels')} className="hidden sm:inline-flex">
        <Tag className="size-[18px]" />
      </ActionButton>
      {(inTrash || inSpam) && (
        <ActionButton label="Move to Inbox" disabled={!hasSelection} onClick={() => commands.moveToInbox(selected)}>
          <Inbox className="size-[18px]" />
        </ActionButton>
      )}

      <Dropdown
        trigger={({ toggle }) => (
          <IconButton label="More actions" onClick={toggle} className="hidden sm:inline-flex">
            <Ellipsis className="size-[18px]" />
          </IconButton>
        )}
        align="end"
      >
        {(close) => (
          <>
            <MenuItem onSelect={() => { commands.toggleReadState(selected); close(); }} disabled={!hasSelection}>
              {anyUnread ? 'Mark as read' : 'Mark as unread'}
            </MenuItem>
            <MenuItem onSelect={() => { actions.setImportant(selected, true); close(); }} disabled={!hasSelection}>
              Mark as important
            </MenuItem>
            <MenuItem onSelect={() => { actions.setImportant(selected, false); close(); }} disabled={!hasSelection}>
              Mark as not important
            </MenuItem>
            <MenuItem onSelect={() => { close(); openMenuFromPoint(selected, 'labels'); }} disabled={!hasSelection}>
              Apply label…
            </MenuItem>
            {(inTrash || inSpam) && (
              <MenuItem onSelect={() => { emptyFolder(); close(); }} danger>
                {inTrash ? 'Empty Trash now' : 'Delete all spam'}
              </MenuItem>
            )}
          </>
        )}
      </Dropdown>

      <div className="ml-auto flex items-center gap-1 text-xs text-ink-3">
        <span className="whitespace-nowrap tabular-nums">
          {total === 0 ? '0 of 0' : `${from}–${to} of ${total}`}
        </span>
        <IconButton label="Newer conversations" disabled={page <= 0} onClick={() => onPage(page - 1)} className="size-8">
          <ChevronLeft className="size-4" />
        </IconButton>
        <IconButton label="Older conversations" disabled={page >= pageCount - 1} onClick={() => onPage(page + 1)} className="size-8">
          <ChevronRight className="size-4" />
        </IconButton>
      </div>
    </div>
  );
}

function openMenuFromPoint(ids: string[], kind: 'labels') {
  commands.openMenu({ kind, ids, x: window.innerWidth / 2 - 150, y: 120 });
}

function ActionButton({
  label,
  disabled,
  onClick,
  className,
  children,
}: {
  label: string;
  disabled?: boolean;
  onClick: (e: MouseEvent<HTMLButtonElement>) => void;
  className?: string;
  children: ReactNode;
}) {
  return (
    <IconButton label={label} disabled={disabled} onClick={onClick} className={cn('size-9', className)}>
      {children}
    </IconButton>
  );
}

export { Button };

