import * as ops from '../domain/ops';
import { createIncomingThread, createSeedData, nextIncomingDelay } from '../domain/seed';
import type {
  Address,
  Draft,
  LabelColor,
  Location,
  MailData,
  Outgoing,
  Settings,
  Thread,
} from '../domain/types';
import { useMail } from './mailStore';

const update = (fn: (d: MailData) => MailData): void => useMail.getState().update(fn);
export const getData = (): MailData => useMail.getState().data;

export const snapshotThreads = (ids: string[]): Thread[] => {
  const set = new Set(ids);
  return getData().threads.filter((t) => set.has(t.id));
};

export const restoreThreads = (snapshot: Thread[]): void => update((d) => ops.replaceThreads(d, snapshot));
export const moveTo = (ids: string[], location: Location): void => update((d) => ops.moveThreads(d, ids, location));
export const setRead = (ids: string[], read: boolean): void => update((d) => ops.setRead(d, ids, read));
export const setMessageUnread = (threadId: string, messageId: string, unread: boolean): void =>
  update((d) => ops.setMessageUnread(d, threadId, messageId, unread));
export const setStarred = (ids: string[], on: boolean): void => update((d) => ops.setStarred(d, ids, on));
export const setImportant = (ids: string[], on: boolean): void => update((d) => ops.setImportant(d, ids, on));
export const snooze = (ids: string[], until: number | null): void => update((d) => ops.snoozeThreads(d, ids, until));
export const toggleLabel = (ids: string[], labelId: string, on: boolean): void =>
  update((d) => ops.toggleLabel(d, ids, labelId, on));
export const removeThreads = (ids: string[]): void => update((d) => ops.removeThreads(d, ids));

export function createLabel(name: string, color: LabelColor): string {
  let id = '';
  update((d) => {
    const result = ops.addLabel(d, name, color);
    id = result.label.id;
    return result.data;
  });
  return id;
}

export const deleteLabel = (labelId: string): void => update((d) => ops.deleteLabel(d, labelId));

export const saveDraft = (draft: Draft): void => update((d) => ops.saveDraft(d, draft));
export const removeDraft = (draftId: string): void => update((d) => ops.removeDraft(d, draftId));
export const queueOutgoing = (out: Outgoing): void => update((d) => ops.queueOutgoing(d, out));

export function cancelOutgoing(outId: string): Draft | null {
  const box: { draft: Draft | null } = { draft: null };
  update((d) => {
    const result = ops.cancelOutgoing(d, outId, Date.now());
    box.draft = result.draft;
    return result.data;
  });
  return box.draft;
}

export const sendOutgoingNow = (outId: string): void =>
  update((d) => ops.rescheduleOutgoing(d, outId, Date.now()));

export const updateSettings = (patch: Partial<Settings>): void => update((d) => ops.updateSettings(d, patch));
export const updateAccount = (patch: Partial<Address>): void => update((d) => ops.updateAccount(d, patch));
export const addRecentSearch = (query: string): void => update((d) => ops.addRecentSearch(d, query));
export const resetData = (): void => useMail.setState({ data: createSeedData(Date.now()) });

export interface TickEvents {
  delivered: Outgoing[];
  woke: Thread[];
  incoming: Thread[];
}

/** Time-driven state changes: send due mail, wake snoozes, receive simulated new mail. */
export function tick(now: number, online: boolean): TickEvents {
  const events: TickEvents = { delivered: [], woke: [], incoming: [] };
  const snapshot = getData();
  const due = online ? snapshot.outgoing.filter((o) => o.sendAt <= now) : [];
  const woke = snapshot.threads.filter((t) => t.snoozedUntil !== null && t.snoozedUntil <= now);
  const incomingDue = snapshot.settings.incomingMail && now >= snapshot.nextIncomingAt;
  if (due.length === 0 && woke.length === 0 && !incomingDue) return events;

  update((d) => {
    let next = d;
    for (const out of due) {
      if (!next.outgoing.some((o) => o.id === out.id)) continue;
      next = ops.deliver(next, out, now);
      events.delivered.push(out);
    }
    if (woke.length > 0) {
      next = ops.wakeSnoozed(next, now);
      events.woke.push(...woke);
    }
    if (incomingDue) {
      const thread = createIncomingThread(now);
      next = ops.receiveThread(next, thread);
      next = ops.setNextIncoming(next, now + nextIncomingDelay());
      events.incoming.push(thread);
    }
    return next;
  });
  return events;
}

import { forwardDraft, newDraft, replyDraft } from '../domain/drafts';
import type { Thread } from '../domain/types';
import { uid } from '../lib/ids';
import * as actions from './actions';
import { useUI, type FloatingMenu } from './uiStore';

/*
 * User-level commands shared by the toolbar, rows, thread view and keyboard shortcuts.
 * Each one applies the change, clears selection and offers an undo toast where it makes sense.
 */

const countLabel = (ids: string[], one: string, many: string) =>
  ids.length === 1 ? one : `${ids.length} ${many}`;

function finish(ids: string[], message: string, undo?: () => void): void {
  const ui = useUI.getState();
  ui.setSelected(ui.selected.filter((id) => !ids.includes(id)));
  ui.toast({ message, actionLabel: undo ? 'Undo' : undefined, onAction: undo, duration: 6000 });
}

export function archiveThreads(ids: string[]): void {
  if (!ids.length) return;
  const snap = actions.snapshotThreads(ids);
  actions.moveTo(ids, 'archive');
  finish(ids, countLabel(ids, 'Conversation archived', 'conversations archived'), () => actions.restoreThreads(snap));
}

export function trashThreads(ids: string[]): void {
  if (!ids.length) return;
  const snap = actions.snapshotThreads(ids);
  actions.moveTo(ids, 'trash');
  finish(ids, countLabel(ids, 'Conversation moved to Trash', 'conversations moved to Trash'), () =>
    actions.restoreThreads(snap),
  );
}

export function reportSpam(ids: string[]): void {
  if (!ids.length) return;
  const snap = actions.snapshotThreads(ids);
  actions.moveTo(ids, 'spam');
  finish(ids, countLabel(ids, 'Conversation moved to Spam', 'conversations moved to Spam'), () =>
    actions.restoreThreads(snap),
  );
}

export function moveToInbox(ids: string[]): void {
  if (!ids.length) return;
  const snap = actions.snapshotThreads(ids);
  actions.moveTo(ids, 'inbox');
  finish(ids, 'Moved to Inbox', () => actions.restoreThreads(snap));
}

export function deleteForever(ids: string[]): void {
  if (!ids.length) return;
  actions.removeThreads(ids);
  finish(ids, 'Conversation deleted forever');
}

export function setReadState(ids: string[], read: boolean): void {
  if (!ids.length) return;
  actions.setRead(ids, read);
  useUI.getState().setSelected(useUI.getState().selected.filter((id) => !ids.includes(id)));
}

export function toggleReadState(ids: string[]): void {
  const threads = actions.getData().threads.filter((t) => ids.includes(t.id));
  const allRead = threads.every((t) => t.messages.every((m) => !m.unread));
  setReadState(ids, !allRead);
}

export function toggleStar(ids: string[]): void {
  if (!ids.length) return;
  const threads = actions.getData().threads.filter((t) => ids.includes(t.id));
  actions.setStarred(ids, !threads.every((t) => t.starred));
}

export function snoozeThreads(ids: string[], until: number, label: string): void {
  if (!ids.length) return;
  const snap = actions.snapshotThreads(ids);
  actions.snooze(ids, until);
  finish(ids, `Snoozed until ${label}`, () => actions.restoreThreads(snap));
}

export function unsnoozeThreads(ids: string[]): void {
  if (!ids.length) return;
  const snap = actions.snapshotThreads(ids);
  actions.snooze(ids, null);
  finish(ids, 'Snooze removed', () => actions.restoreThreads(snap));
}

export function applyLabel(ids: string[], labelId: string, on: boolean): void {
  if (!ids.length) return;
  actions.toggleLabel(ids, labelId, on);
}

export function openMenu(menu: FloatingMenu): void {
  useUI.getState().openMenu(menu);
}

export function startNewCompose(): void {
  const data = actions.getData();
  const draft = newDraft(uid('draft'), data.settings.signature, Date.now());
  actions.saveDraft(draft);
  useUI.getState().openCompose(draft.id);
}

export function startReplyCompose(thread: Thread, mode: 'reply' | 'replyAll'): string {
  const data = actions.getData();
  const existing = data.drafts.find(
    (d) => d.threadId === thread.id && (d.mode === 'reply' || d.mode === 'replyAll'),
  );
  if (existing) return existing.id;
  const draft = replyDraft(uid('draft'), thread, mode, data.account, Date.now());
  actions.saveDraft(draft);
  return draft.id;
}

export function startForwardCompose(thread: Thread): void {
  const draft = forwardDraft(uid('draft'), thread, Date.now());
  actions.saveDraft(draft);
  useUI.getState().openCompose(draft.id);
}

export function reopenDraft(draftId: string): void {
  useUI.getState().openCompose(draftId);
}

import { create } from 'zustand';
import type { Category } from '../domain/types';
import { uid } from '../lib/ids';

export interface ToastItem {
  id: string;
  message: string;
  actionLabel?: string;
  onAction?: () => void;
  duration: number;
}

export interface ConfirmState {
  title: string;
  body?: string;
  confirmLabel: string;
  danger?: boolean;
  onConfirm: () => void;
}

export interface FloatingMenu {
  kind: 'snooze' | 'labels';
  ids: string[];
  x: number;
  y: number;
}

export interface PendingReply {
  threadId: string;
  mode: 'reply' | 'replyAll';
  nonce: number;
}

export type SidebarMode = 'expanded' | 'rail';

interface UIState {
  toasts: ToastItem[];
  composeIds: string[];
  minimizedIds: string[];
  maximizedId: string | null;
  selected: string[];
  focusedId: string | null;
  page: number;
  category: Category;
  settingsOpen: boolean;
  shortcutsOpen: boolean;
  confirm: ConfirmState | null;
  drawerOpen: boolean;
  sidebarMode: SidebarMode;
  menu: FloatingMenu | null;
  pendingReply: PendingReply | null;
  refreshing: boolean;
  toast: (t: Omit<ToastItem, 'id' | 'duration'> & { duration?: number }) => void;
  dismissToast: (id: string) => void;
  openCompose: (id: string) => void;
  closeCompose: (id: string) => void;
  toggleMinimize: (id: string) => void;
  toggleMaximize: (id: string) => void;
  setSelected: (ids: string[]) => void;
  toggleSelected: (id: string) => void;
  setFocusedId: (id: string | null) => void;
  setPage: (page: number) => void;
  setCategory: (category: Category) => void;
  setSettingsOpen: (open: boolean) => void;
  setShortcutsOpen: (open: boolean) => void;
  ask: (confirm: ConfirmState) => void;
  closeConfirm: () => void;
  setDrawerOpen: (open: boolean) => void;
  toggleSidebar: () => void;
  openMenu: (menu: FloatingMenu) => void;
  closeMenu: () => void;
  requestReply: (threadId: string, mode: 'reply' | 'replyAll') => void;
  consumeReply: () => void;
  setRefreshing: (refreshing: boolean) => void;
}

export const useUI = create<UIState>()((set, get) => ({
  toasts: [],
  composeIds: [],
  minimizedIds: [],
  maximizedId: null,
  selected: [],
  focusedId: null,
  page: 0,
  category: 'primary',
  settingsOpen: false,
  shortcutsOpen: false,
  confirm: null,
  drawerOpen: false,
  sidebarMode: typeof window !== 'undefined' && window.innerWidth >= 1100 ? 'expanded' : 'rail',
  menu: null,
  pendingReply: null,
  refreshing: false,

  toast: (t) => {
    const id = uid('toast');
    const duration = t.duration ?? 6000;
    set((s) => ({ toasts: [...s.toasts.slice(-2), { ...t, id, duration }] }));
    window.setTimeout(() => get().dismissToast(id), duration);
  },
  dismissToast: (id) => set((s) => ({ toasts: s.toasts.filter((t) => t.id !== id) })),

  openCompose: (id) =>
    set((s) => ({
      composeIds: [...s.composeIds.filter((x) => x !== id), id].slice(-3),
      minimizedIds: s.minimizedIds.filter((x) => x !== id),
    })),
  closeCompose: (id) =>
    set((s) => ({
      composeIds: s.composeIds.filter((x) => x !== id),
      minimizedIds: s.minimizedIds.filter((x) => x !== id),
      maximizedId: s.maximizedId === id ? null : s.maximizedId,
    })),
  toggleMinimize: (id) =>
    set((s) => ({
      minimizedIds: s.minimizedIds.includes(id)
        ? s.minimizedIds.filter((x) => x !== id)
        : [...s.minimizedIds, id],
      maximizedId: s.maximizedId === id ? null : s.maximizedId,
    })),
  toggleMaximize: (id) =>
    set((s) => ({
      maximizedId: s.maximizedId === id ? null : id,
      minimizedIds: s.minimizedIds.filter((x) => x !== id),
    })),

  setSelected: (ids) => set({ selected: Array.from(new Set(ids)) }),
  toggleSelected: (id) =>
    set((s) => ({
      selected: s.selected.includes(id) ? s.selected.filter((x) => x !== id) : [...s.selected, id],
    })),
  setFocusedId: (id) => set({ focusedId: id }),
  setPage: (page) => set({ page }),
  setCategory: (category) => set({ category, page: 0 }),
  setSettingsOpen: (open) => set({ settingsOpen: open }),
  setShortcutsOpen: (open) => set({ shortcutsOpen: open }),
  ask: (confirm) => set({ confirm }),
  closeConfirm: () => set({ confirm: null }),
  setDrawerOpen: (open) => set({ drawerOpen: open }),
  toggleSidebar: () => set((s) => ({ sidebarMode: s.sidebarMode === 'expanded' ? 'rail' : 'expanded' })),
  openMenu: (menu) => set({ menu }),
  closeMenu: () => set({ menu: null }),
  requestReply: (threadId, mode) => set({ pendingReply: { threadId, mode, nonce: Date.now() } }),
  consumeReply: () => set({ pendingReply: null }),
  setRefreshing: (refreshing) => set({ refreshing }),
}));

import { htmlToText } from '../lib/text';
import { searchThreads } from '../lib/search';
import type { Section } from '../lib/route';
import { draftHasContent } from './drafts';
import { isExcluded, isUnread, sentBy, sortRecent } from './threads';
import type { Address, Category, Folder, MailData, Thread } from './types';

export const PAGE_SIZE = 50;

export function folderThreads(d: MailData, folder: Folder): Thread[] {
  const me = d.account.email;
  switch (folder) {
    case 'inbox':
      return sortRecent(d.threads.filter((t) => t.location === 'inbox' && t.snoozedUntil === null));
    case 'starred':
      return sortRecent(d.threads.filter((t) => t.starred && !isExcluded(t)));
    case 'snoozed':
      return sortRecent(d.threads.filter((t) => t.snoozedUntil !== null && !isExcluded(t)));
    case 'sent':
      return sortRecent(d.threads.filter((t) => sentBy(t, me) && !isExcluded(t)));
    case 'all':
      return sortRecent(d.threads.filter((t) => !isExcluded(t)));
    case 'spam':
      return sortRecent(d.threads.filter((t) => t.location === 'spam'));
    case 'trash':
      return sortRecent(d.threads.filter((t) => t.location === 'trash'));
    default:
      return [];
  }
}

export function labelThreads(d: MailData, labelId: string): Thread[] {
  return sortRecent(d.threads.filter((t) => t.labelIds.includes(labelId) && !isExcluded(t)));
}

export function listThreads(
  d: MailData,
  section: Section,
  category: Category,
  now: number,
): Thread[] {
  if (section.kind === 'label') return labelThreads(d, section.labelId);
  if (section.kind === 'search') {
    return searchThreads(d.threads, section.q, { account: d.account.email, labels: d.labels, now });
  }
  if (section.folder === 'drafts' || section.folder === 'scheduled') return [];
  const list = folderThreads(d, section.folder);
  if (section.folder === 'inbox' && d.settings.categories) {
    return list.filter((t) => t.category === category);
  }
  return list;
}

export function categoryUnread(d: MailData): Record<Category, number> {
  const counts: Record<Category, number> = { primary: 0, social: 0, promotions: 0, updates: 0 };
  for (const t of folderThreads(d, 'inbox')) {
    if (isUnread(t)) counts[t.category] += 1;
  }
  return counts;
}

export function visibleDrafts(d: MailData): MailData['drafts'] {
  return [...d.drafts].filter(draftHasContent).sort((a, b) => b.updatedAt - a.updatedAt);
}

export function scheduledItems(d: MailData): MailData['outgoing'] {
  return d.outgoing.filter((o) => o.kind !== 'undo').sort((a, b) => a.sendAt - b.sendAt);
}

export function sidebarCounts(d: MailData) {
  return {
    inboxUnread: folderThreads(d, 'inbox').filter(isUnread).length,
    drafts: visibleDrafts(d).length,
    scheduled: scheduledItems(d).length,
    spamUnread: d.threads.filter((t) => t.location === 'spam' && isUnread(t)).length,
  };
}

export function draftThreadIds(d: MailData): Set<string> {
  const ids = new Set<string>();
  for (const draft of d.drafts) if (draft.threadId && draftHasContent(draft)) ids.add(draft.threadId);
  return ids;
}

export function storageBytes(d: MailData): number {
  let total = 0;
  for (const t of d.threads) {
    for (const m of t.messages) {
      total += m.text.length;
      for (const a of m.attachments) total += a.size;
    }
  }
  return total;
}

export interface Contact {
  name: string;
  email: string;
  count: number;
}

export function contactsOf(account: Address, threads: Thread[]): Contact[] {
  const map = new Map<string, Contact>();
  const add = (a: Address) => {
    if (!a.email || a.email.toLowerCase() === account.email.toLowerCase()) return;
    const key = a.email.toLowerCase();
    const existing = map.get(key);
    if (existing) {
      existing.count += 1;
      if (!existing.name && a.name) existing.name = a.name;
    } else {
      map.set(key, { name: a.name, email: a.email, count: 1 });
    }
  };
  for (const t of threads) {
    for (const m of t.messages) {
      add(m.from);
      m.to.forEach(add);
      m.cc.forEach(add);
    }
  }
  return [...map.values()].sort((a, b) => b.count - a.count);
}

export const FOLDERS = [
  'inbox',
  'starred',
  'snoozed',
  'sent',
  'drafts',
  'scheduled',
  'all',
  'spam',
  'trash',
] as const;
export type Folder = (typeof FOLDERS)[number];

export const FOLDER_LABELS: Record<Folder, string> = {
  inbox: 'Inbox',
  starred: 'Starred',
  snoozed: 'Snoozed',
  sent: 'Sent',
  drafts: 'Drafts',
  scheduled: 'Scheduled',
  all: 'All Mail',
  spam: 'Spam',
  trash: 'Trash',
};

/** Where a conversation physically lives. Folders are derived from this plus flags. */
export type Location = 'inbox' | 'archive' | 'spam' | 'trash';

export const CATEGORIES = ['primary', 'social', 'promotions', 'updates'] as const;
export type Category = (typeof CATEGORIES)[number];

export const LABEL_COLORS = ['blue', 'red', 'green', 'amber', 'violet', 'pink', 'teal', 'slate'] as const;
export type LabelColor = (typeof LABEL_COLORS)[number];

export type AttachmentKind = 'pdf' | 'image' | 'sheet' | 'doc' | 'slides' | 'archive' | 'file';
export type ComposeMode = 'new' | 'reply' | 'replyAll' | 'forward';

export interface Address {
  name: string;
  email: string;
}

export interface Attachment {
  id: string;
  name: string;
  size: number;
  kind: AttachmentKind;
}

export interface Message {
  id: string;
  from: Address;
  to: Address[];
  cc: Address[];
  date: number;
  html: string;
  text: string;
  attachments: Attachment[];
  unread: boolean;
}

export interface Thread {
  id: string;
  subject: string;
  messages: Message[];
  location: Location;
  category: Category;
  starred: boolean;
  important: boolean;
  labelIds: string[];
  snoozedUntil: number | null;
}

export interface Label {
  id: string;
