      <div
        role="dialog"
        aria-modal="true"
        aria-label={title}
        className={cn(
          'flex w-full flex-col overflow-hidden bg-surface text-ink shadow-2xl sm:rounded-2xl',
          tall ? 'sm:h-[85vh]' : 'sm:max-h-[90vh]',
          width,
        )}
      >
        <div className="flex shrink-0 items-center justify-between border-b border-line px-5 py-3.5">
