import type { Attachment } from '../domain/types';

/** In-session file contents for attachments added through compose (not persisted). */
const blobs = new Map<string, Blob>();

export function registerBlob(id: string, blob: Blob): void {
  blobs.set(id, blob);
}

function placeholderImage(name: string): Promise<Blob> {
  const canvas = document.createElement('canvas');
  canvas.width = 1200;
  canvas.height = 800;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    const gradient = ctx.createLinearGradient(0, 0, 1200, 800);
    gradient.addColorStop(0, '#8ab4f8');
    gradient.addColorStop(1, '#c58af9');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, 1200, 800);
    ctx.fillStyle = 'rgba(255,255,255,0.92)';
    ctx.font = '600 56px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(name, 600, 410);
  }
  return new Promise((resolve) => {
    canvas.toBlob((blob) => resolve(blob ?? new Blob()), 'image/png');
  });
}

export async function attachmentBlob(attachment: Attachment): Promise<Blob> {
  const existing = blobs.get(attachment.id);
  if (existing) return existing;
  if (attachment.kind === 'image') return placeholderImage(attachment.name);
  return new Blob([`Preview placeholder for ${attachment.name}\n`], { type: 'text/plain' });
}

export async function downloadAttachment(attachment: Attachment): Promise<void> {
  const blob = await attachmentBlob(attachment);
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = attachment.name;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

import type { AttachmentKind } from '../domain/types';

export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 ** 2) return `${Math.round(bytes / 1024)} KB`;
  if (bytes < 1024 ** 3) return `${(bytes / 1024 ** 2).toFixed(1)} MB`;
  return `${(bytes / 1024 ** 3).toFixed(2)} GB`;
}

export function initials(name: string, email: string): string {
  const source = name.trim() || email;
  const parts = source.split(/[\s._@-]+/).filter(Boolean);
  const letters = parts.length >= 2 ? `${parts[0][0]}${parts[1][0]}` : source.slice(0, 1);
  return letters.toUpperCase();
}

export function hueFor(text: string): number {
  let hash = 0;
  for (const char of text) hash = (hash * 31 + char.charCodeAt(0)) % 360;
  return hash;
}

const KIND_BY_EXT: Record<string, AttachmentKind> = {
  pdf: 'pdf',
  png: 'image',
  jpg: 'image',
  jpeg: 'image',
  gif: 'image',
  webp: 'image',
  heic: 'image',
  xls: 'sheet',
  xlsx: 'sheet',
  csv: 'sheet',
  ppt: 'slides',
  pptx: 'slides',
  key: 'slides',
  doc: 'doc',
  docx: 'doc',
  txt: 'doc',
  md: 'doc',
  zip: 'archive',
  tar: 'archive',
  gz: 'archive',
  '7z': 'archive',
};

export function kindFromName(name: string): AttachmentKind {
  const ext = name.split('.').pop()?.toLowerCase() ?? '';
  return KIND_BY_EXT[ext] ?? 'file';
}

export function plural(count: number, word: string): string {
  return `${count} ${word}${count === 1 ? '' : 's'}`;
}

const ALLOWED = new Set([
  'P', 'BR', 'DIV', 'SPAN', 'B', 'STRONG', 'I', 'EM', 'U', 'S', 'STRIKE', 'A', 'UL', 'OL', 'LI',
  'BLOCKQUOTE', 'H1', 'H2', 'H3', 'H4', 'CODE', 'PRE', 'HR', 'DETAILS', 'SUMMARY', 'MARK',
]);

const DROPPED = new Set([
  'SCRIPT', 'STYLE', 'IFRAME', 'OBJECT', 'EMBED', 'IMG', 'VIDEO', 'AUDIO', 'LINK', 'META', 'FORM',
  'INPUT', 'BUTTON', 'TEXTAREA', 'SELECT', 'SVG', 'MATH', 'TEMPLATE', 'NOSCRIPT',
]);

/**
 * Whitelist sanitizer for mail HTML. Keeps basic text formatting, safe links and
 * quoted replies (wrapped in a collapsible <details>, like Gmail's "trimmed content").
 */
export function sanitizeHtml(html: string): string {
  if (!html) return '';
  const template = document.createElement('template');
  template.innerHTML = html;
  cleanChildren(template.content);
  return template.innerHTML;
}

function cleanChildren(parent: Node) {
  for (const node of Array.from(parent.childNodes)) {
    if (node.nodeType === Node.TEXT_NODE) continue;
    if (node.nodeType !== Node.ELEMENT_NODE) {
      node.parentNode?.removeChild(node);
      continue;
    }
    const el = node as HTMLElement;
    if (DROPPED.has(el.tagName)) {
      el.remove();
      continue;
    }
    if (!ALLOWED.has(el.tagName)) {
      cleanChildren(el);
      el.replaceWith(...Array.from(el.childNodes));
      continue;
    }
    for (const attr of Array.from(el.attributes)) {
      const keepLink = el.tagName === 'A' && attr.name === 'href' && /^(https?:|mailto:)/i.test(attr.value.trim());
      const keepQuote = el.tagName === 'BLOCKQUOTE' && attr.name === 'class' && attr.value === 'quote';
      if (!keepLink && !keepQuote) el.removeAttribute(attr.name);
    }
    if (el.tagName === 'A') {
      el.setAttribute('target', '_blank');
      el.setAttribute('rel', 'noreferrer noopener');
    }
    cleanChildren(el);
    if (el.tagName === 'BLOCKQUOTE' && el.classList.contains('quote')) {
      const details = document.createElement('details');
      details.className = 'quote-toggle';
      const summary = document.createElement('summary');
      summary.textContent = 'Show trimmed content';
      el.replaceWith(details);
      details.append(summary, el);
    }
  }
}

import { escapeHtml, htmlToText } from '../lib/text';
import { formatFullDate } from '../lib/time';
import { lastMessage } from './threads';
import type { Address, ComposeMode, Draft, Thread } from './types';

export function newDraft(id: string, signature: string, now: number): Draft {
  const sig = signature
    .split('\n')
    .map((line) => escapeHtml(line))
    .join('<br>');
  return {
    id,
    threadId: null,
    mode: 'new',
    to: [],
    cc: [],
    bcc: [],
    subject: '',
    html: sig ? `<p><br></p><p>-- <br>${sig}</p>` : '<p><br></p>',
    attachments: [],
    updatedAt: now,
    pristine: true,
  };
}

const addrKey = (a: Address) => a.email.toLowerCase();

export function replyDraft(
  id: string,
  thread: Thread,
  mode: Extract<ComposeMode, 'reply' | 'replyAll'>,
  me: Address,
  now: number,
): Draft {
  const last = lastMessage(thread);
  const isMe = (a: Address) => addrKey(a) === addrKey(me);
  const to = dedupe((last.from.email === me.email ? last.to : [last.from]).filter((a) => !isMe(a)));
  const toKeys = new Set(to.map(addrKey));
  const cc =
    mode === 'replyAll'
      ? dedupe([...last.to, ...last.cc]).filter((a) => !isMe(a) && !toKeys.has(addrKey(a)))
      : [];
  const subject = /^re:/i.test(thread.subject) ? thread.subject : `Re: ${thread.subject}`;
  const stamp = `On ${formatFullDate(last.date)}, ${escapeHtml(last.from.name || last.from.email)} &lt;${escapeHtml(
    last.from.email,
  )}&gt; wrote:`;
  return {
    id,
    threadId: thread.id,
    mode,
    to,
    cc,
    bcc: [],
    subject,
    html: `<p><br></p><p>${stamp}</p><blockquote class="quote">${last.html}</blockquote>`,
    attachments: [],
    updatedAt: now,
    pristine: false,
  };
}

export function forwardDraft(id: string, thread: Thread, now: number): Draft {
  const last = lastMessage(thread);
  const subject = /^fwd?:/i.test(thread.subject) ? thread.subject : `Fwd: ${thread.subject}`;
  const header = [
    '---------- Forwarded message ---------',
    `From: ${last.from.name} &lt;${escapeHtml(last.from.email)}&gt;`,
    `Date: ${escapeHtml(formatFullDate(last.date))}`,
    `Subject: ${escapeHtml(thread.subject)}`,
    `To: ${escapeHtml(last.to.map((a) => a.email).join(', '))}`,
  ].join('<br>');
  return {
    id,
    threadId: null,
    mode: 'forward',
    to: [],
    cc: [],
    bcc: [],
    subject,
    html: `<p><br></p><p>${header}</p><blockquote>${last.html}</blockquote>`,
    attachments: [...last.attachments],
    updatedAt: now,
    pristine: false,
  };
}

export function draftHasContent(draft: Draft): boolean {
  if (draft.to.length || draft.cc.length || draft.bcc.length || draft.attachments.length) return true;
  if (draft.subject.trim()) return true;
  return !draft.pristine && htmlToText(draft.html).length > 0;
}

function dedupe(list: Address[]): Address[] {
  const seen = new Set<string>();
  return list.filter((a) => {
    const key = addrKey(a);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

import type { ButtonHTMLAttributes } from 'react';
import { cn } from '../../lib/cn';

type Variant = 'primary' | 'secondary' | 'ghost' | 'danger';

export function Button({
  variant = 'primary',
  size = 'md',
  className,
  ...rest
}: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: Variant; size?: 'sm' | 'md' }) {
  return (
    <button
      type="button"
      className={cn(
        'inline-flex shrink-0 items-center justify-center gap-2 rounded-full font-medium transition disabled:pointer-events-none disabled:opacity-40 focus-visible:outline-2 focus-visible:outline-primary',
        size === 'sm' ? 'h-8 px-3.5 text-sm' : 'h-10 px-5 text-sm',
        variant === 'primary' && 'bg-primary text-on-primary shadow-sm hover:brightness-110',
        variant === 'secondary' && 'border border-line bg-surface text-primary hover:bg-hover',
        variant === 'ghost' && 'text-primary hover:bg-primary-soft/60',
        variant === 'danger' && 'bg-danger text-white hover:brightness-110',
        className,
      )}
      {...rest}
    />
  );
}

import type { LabelColor } from '../domain/types';

export const LABEL_DOT: Record<LabelColor, string> = {
  blue: 'bg-[#1a73e8]',
  red: 'bg-[#d93025]',
  green: 'bg-[#188038]',
  amber: 'bg-[#f29900]',
  violet: 'bg-[#8430ce]',
  pink: 'bg-[#d01884]',
  teal: 'bg-[#129eaf]',
  slate: 'bg-[#5f6368]',
};

export const LABEL_CHIP: Record<LabelColor, string> = {
  blue: 'bg-[#d3e3fd] text-[#0842a0] dark:bg-[#1f3a5f] dark:text-[#a8c7fa]',
  red: 'bg-[#fce8e6] text-[#a50e0e] dark:bg-[#5c2b29] dark:text-[#f2b8b5]',
