/* Toasts ---------------------------------------------------------------- */

export function Toaster() {
  const toasts = useUI((s) => s.toasts);
  const dismiss = useUI((s) => s.dismissToast);
  return (
    <div
      aria-live="polite"
      className="pointer-events-none fixed inset-x-3 bottom-4 z-[80] flex flex-col items-start gap-2 sm:inset-x-auto sm:left-4"
    >
      {toasts.map((t) => (
        <div
          key={t.id}
          role="status"
          className="animate-toast pointer-events-auto flex w-full max-w-md items-center gap-3 rounded-lg bg-[#303030] py-2.5 pl-4 pr-2 text-sm text-[#f5f5f5] shadow-xl sm:w-auto sm:min-w-[300px]"
        >
          <span className="flex-1">{t.message}</span>
          {t.actionLabel && (
            <button
              type="button"
              className="rounded px-2 py-1 font-medium text-[#a8c7fa] hover:bg-white/10"
              onClick={() => {
                t.onAction?.();
                dismiss(t.id);
              }}
            >
              {t.actionLabel}
            </button>
          )}
          <button
            type="button"
            aria-label="Dismiss"
            className="rounded-full p-1.5 text-white/70 hover:bg-white/10"
            onClick={() => dismiss(t.id)}
          >
            <X className="size-4" />
          </button>
        </div>
      ))}
    </div>
  );
}

/* Floating menus (snooze + labels) -------------------------------------- */

export function FloatingMenus() {
  const menu = useUI((s) => s.menu);
  const close = useUI((s) => s.closeMenu);
  if (!menu) return null;
  const left = Math.max(8, Math.min(menu.x, window.innerWidth - 308));
  const top = Math.max(8, Math.min(menu.y + 6, window.innerHeight - 440));
  return (
    <>
      <div className="fixed inset-0 z-[55]" onMouseDown={close} aria-hidden />
      <div
        role="menu"
        className="fixed z-[60] w-[300px] rounded-xl border border-line bg-surface p-1.5 text-ink shadow-2xl max-sm:inset-x-2 max-sm:bottom-2 max-sm:top-auto max-sm:w-auto"
        style={{ left: undefined, top: undefined, ...(window.innerWidth >= 640 ? { left, top } : {}) }}
      >
        {menu.kind === 'snooze' ? <SnoozePanel ids={menu.ids} onDone={close} /> : <LabelPanel ids={menu.ids} onDone={close} />}
      </div>
    </>
  );
}

function SnoozePanel({ ids, onDone }: { ids: string[]; onDone: () => void }) {
  const now = Date.now();
  const presets = snoozePresets(now);
  const [custom, setCustom] = useState(() => toLocalInput(now + 3 * 3_600_000));
  const anySnoozed = useMail((s) => s.data.threads.some((t) => ids.includes(t.id) && t.snoozedUntil !== null));

  const apply = (at: number) => {
    commands.snoozeThreads(ids, at, formatSendAt(at, Date.now()));
    onDone();
  };

  const submitCustom = (e: FormEvent) => {
    e.preventDefault();
    const at = fromLocalInput(custom);
    if (Number.isFinite(at) && at > Date.now()) apply(at);
  };

  return (
    <div>
      <p className="px-3 pb-1 pt-2 text-xs font-medium uppercase tracking-wide text-ink-3">Snooze until</p>
      {presets.map((p) => (
        <MenuItem key={p.key} icon={<Clock />} onSelect={() => apply(p.at)}>
          <span className="flex items-center justify-between gap-3">
            <span>{p.label}</span>
            <span className="text-xs text-ink-3">{formatSendAt(p.at, now)}</span>
          </span>
        </MenuItem>
      ))}
      <form onSubmit={submitCustom} className="mt-1 border-t border-line px-2 pb-1 pt-2">
        <label className="mb-1.5 block text-xs text-ink-3" htmlFor="snooze-custom">
          Pick date and time
        </label>
        <div className="flex items-center gap-2">
          <input
            id="snooze-custom"
            type="datetime-local"
            value={custom}
            onChange={(e) => setCustom(e.target.value)}
            className="min-w-0 flex-1 rounded-lg border border-line bg-surface px-2 py-1.5 text-sm outline-none focus:border-primary"
          />
          <Button type="submit" size="sm">
            Snooze
          </Button>
        </div>
      </form>
      {anySnoozed && (
        <div className="border-t border-line pt-1">
          <MenuItem
            onSelect={() => {
              commands.unsnoozeThreads(ids);
              onDone();
            }}
          >
            Remove snooze
          </MenuItem>
        </div>
      )}
    </div>
  );
}

function LabelPanel({ ids, onDone }: { ids: string[]; onDone: () => void }) {
  const labels = useMail((s) => s.data.labels);
  const threads = useMail((s) => s.data.threads.filter((t) => ids.includes(t.id)));
  const [name, setName] = useState('');

  const stateOf = (labelId: string): 'all' | 'some' | 'none' => {
    const count = threads.filter((t) => t.labelIds.includes(labelId)).length;
    if (count === 0) return 'none';
    return count === threads.length ? 'all' : 'some';
  };

  const submitNew = (e: FormEvent) => {
    e.preventDefault();
    const trimmed = name.trim();
    if (!trimmed) return;
    const color: LabelColor = LABEL_COLORS[labels.length % LABEL_COLORS.length];
    const id = createLabel(trimmed, color);
    commands.applyLabel(ids, id, true);
    setName('');
    onDone();
  };

  return (
    <div>
      <p className="px-3 pb-1 pt-2 text-xs font-medium uppercase tracking-wide text-ink-3">Label as</p>
      <div className="max-h-64 overflow-y-auto">
        {labels.map((label) => {
          const state = stateOf(label.id);
          return (
            <label
              key={label.id}
              className="flex cursor-pointer items-center gap-3 rounded-lg px-3 py-2 text-sm hover:bg-hover"
            >
              <input
                type="checkbox"
                className="size-4 accent-primary"
                checked={state === 'all'}
                onChange={() => commands.applyLabel(ids, label.id, state !== 'all')}
              />
              <span className={cn('size-2.5 rounded-full', LABEL_DOT[label.color])} />
              <span className="flex-1 truncate">{label.name}</span>
              {state === 'some' && <span className="text-xs text-ink-3">Some</span>}
            </label>
          );
        })}
        {labels.length === 0 && <p className="px-3 py-2 text-sm text-ink-3">No labels yet.</p>}
      </div>
      <form onSubmit={submitNew} className="mt-1 flex items-center gap-2 border-t border-line px-2 pb-1 pt-2">
        <Tag className="size-4 shrink-0 text-ink-3" />
        <input
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="Create new label"
          aria-label="Create new label"
          className="min-w-0 flex-1 bg-transparent py-1 text-sm outline-none placeholder:text-ink-3"
        />
        <Button type="submit" size="sm" variant="ghost" disabled={!name.trim()}>
          Create
        </Button>
      </form>
    </div>
  );
}

import { useEffect, useRef } from 'react';
import { listThreads } from '../domain/selectors';
import type { Folder } from '../domain/types';
import { go, goFolder, type Route } from '../lib/route';
import * as commands from '../store/commands';
import { useMail } from '../store/mailStore';
import { useUI } from '../store/uiStore';

function isTyping(target: EventTarget | null): boolean {
  const el = target as HTMLElement | null;
  if (!el) return false;
  return el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.tagName === 'SELECT' || el.isContentEditable;
}

const GO_KEYS: Record<string, Folder> = {
  i: 'inbox',
  s: 'starred',
  n: 'snoozed',
  t: 'sent',
  d: 'drafts',
  a: 'all',
  c: 'scheduled',
};

function anchorFor(rowId: string | null): { x: number; y: number } {
  const el = rowId ? document.getElementById(`row-${rowId}`) : null;
  if (!el) return { x: window.innerWidth / 2 - 140, y: 120 };
  const rect = el.getBoundingClientRect();
  return { x: rect.left + 48, y: rect.bottom };
}

/** Gmail-style single-key shortcuts. Ignored while typing or when a dialog is open. */
export function useShortcuts(route: Route): void {
  const routeRef = useRef(route);
  useEffect(() => {
    routeRef.current = route;
  }, [route]);

  useEffect(() => {
    let gUntil = 0;

    const onKey = (e: KeyboardEvent) => {
      const ui = useUI.getState();
      if (e.key === 'Escape' && ui.menu) {
        ui.closeMenu();
        return;
      }
      if (isTyping(e.target) || e.metaKey || e.ctrlKey || e.altKey) return;
      if (ui.settingsOpen || ui.shortcutsOpen || ui.confirm) return;

      const r = routeRef.current;
      const data = useMail.getState().data;
      const visibleIds = listThreads(data, r.section, ui.category, Date.now()).map((t) => t.id);
      const targets = (): string[] => {
        if (ui.selected.length) return ui.selected;
        if (r.threadId) return [r.threadId];
        return ui.focusedId ? [ui.focusedId] : [];
      };
      const current = r.threadId ?? ui.focusedId;
      const focusedThread = current ? data.threads.find((t) => t.id === current) : undefined;

      if (gUntil > Date.now() && GO_KEYS[e.key]) {
        e.preventDefault();
        gUntil = 0;
        goFolder(GO_KEYS[e.key]);
        return;
      }
      gUntil = 0;

      const move = (delta: number) => {
        if (!visibleIds.length) return;
        if (r.threadId) {
          const idx = visibleIds.indexOf(r.threadId);
          const next = visibleIds[Math.min(visibleIds.length - 1, Math.max(0, idx + delta))];
          if (next && next !== r.threadId) go({ ...r, threadId: next });
          return;
        }
        const idx = ui.focusedId ? visibleIds.indexOf(ui.focusedId) : -1;
        const next = visibleIds[Math.min(visibleIds.length - 1, Math.max(0, idx + delta))];
        ui.setFocusedId(next);
        document.getElementById(`row-${next}`)?.scrollIntoView({ block: 'nearest' });
      };

      const afterLeaving = (ids: string[]) => {
        if (r.threadId && ids.includes(r.threadId)) go({ ...r, threadId: null });
      };

      switch (e.key) {
        case 'c':
          e.preventDefault();
          commands.startNewCompose();
          break;
        case '/':
          e.preventDefault();
          document.getElementById('search-input')?.focus();
          break;
        case 'j':
        case 'n':
          e.preventDefault();
          move(1);
          break;
        case 'k':
        case 'p':
          e.preventDefault();
          move(-1);
          break;
        case 'o':
        case 'Enter':
          if (!r.threadId && ui.focusedId) {
            e.preventDefault();
            go({ ...r, threadId: ui.focusedId });
          }
          break;
        case 'u':
          if (r.threadId) {
            e.preventDefault();
            go({ ...r, threadId: null });
          }
          break;
        case 'e': {
          const ids = targets();
          e.preventDefault();
          commands.archiveThreads(ids);
          afterLeaving(ids);
          break;
        }
        case '#': {
          const ids = targets();
          e.preventDefault();
          if (r.section.kind === 'folder' && r.section.folder === 'trash') commands.deleteForever(ids);
          else commands.trashThreads(ids);
          afterLeaving(ids);
          break;
        }
        case '!': {
          const ids = targets();
          e.preventDefault();
          commands.reportSpam(ids);
          afterLeaving(ids);
          break;
        }
        case 's': {
          e.preventDefault();
          commands.toggleStar(targets());
          break;
        }
        case 'I':
          e.preventDefault();
          commands.setReadState(targets(), true);
          break;
        case 'U':
          e.preventDefault();
          commands.setReadState(targets(), false);
          break;
        case 'x': {
          const id = r.threadId ?? ui.focusedId;
          if (id) {
            e.preventDefault();
            ui.toggleSelected(id);
          }
          break;
        }
        case 'r':
        case 'a':
          if (r.threadId) {
            e.preventDefault();
            ui.requestReply(r.threadId, e.key === 'a' ? 'replyAll' : 'reply');
          }
          break;
        case 'f':
          if (focusedThread) {
            e.preventDefault();
            commands.startForwardCompose(focusedThread);
          }
          break;
        case 'b': {
          const ids = targets();
          if (ids.length) {
            e.preventDefault();
            ui.openMenu({ kind: 'snooze', ids, ...anchorFor(ui.focusedId ?? r.threadId) });
          }
          break;
        }
        case 'l': {
          const ids = targets();
          if (ids.length) {
            e.preventDefault();
            ui.openMenu({ kind: 'labels', ids, ...anchorFor(ui.focusedId ?? r.threadId) });
          }
          break;
        }
        case 'g':
          gUntil = Date.now() + 1200;
          break;
        case '?':
          e.preventDefault();
          ui.setShortcutsOpen(true);
          break;
        default:
          break;
      }
    };

    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);
}

import { create } from 'zustand';
import { createJSONStorage, persist } from 'zustand/middleware';
import { createSeedData } from '../domain/seed';
import type { MailData } from '../domain/types';

export interface MailState {
  data: MailData;
  update: (fn: (data: MailData) => MailData) => void;
}

/** Entire mailbox persisted to localStorage so the app works offline and survives reloads. */
export const useMail = create<MailState>()(
  persist(
    (set) => ({
      data: createSeedData(Date.now()),
      update: (fn) => set((state) => ({ data: fn(state.data) })),
    }),
    {
      name: 'claude-haiku-mail:v1',
      version: 1,
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({ data: state.data }),
    },
  ),
);

import { CircleQuestionMark, Mail, Menu, Settings } from 'lucide-react';
import type { Route } from '../../lib/route';
