          className="min-w-0 flex-1 truncate text-left text-sm font-medium"
        >
          {title}
        </button>
        {!mobile && (
          <>
            <IconButton label={minimized ? 'Restore window' : 'Minimize'} onClick={() => useUI.getState().toggleMinimize(draft.id)} className="size-8">
