            </IconButton>
            <IconButton
              label={maximized ? 'Exit full screen' : 'Full screen'}
              onClick={() => useUI.getState().toggleMaximize(draft.id)}
              className="size-8"
            >
              <Maximize2 className="size-4" />
            </IconButton>
          </>
        )}
