              ref={fileRef}
              type="file"
              multiple
              className="hidden"
              onChange={(e) => {
                addFiles(e.target.files);
                e.target.value = '';
              }}
            />
            <div className="ml-auto" />
            <IconButton label="Discard draft" onClick={discard} className="size-9">
              <Trash className="size-[18px]" />
            </IconButton>
          </footer>
        </>
      )}
    </section>
  );
}

