@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

@theme inline {
  --font-sans: "Google Sans", Roboto, "Segoe UI", system-ui, -apple-system, sans-serif;

  --color-app: var(--app);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-hover: var(--hover);
  --color-selected: var(--selected);
  --color-line: var(--line);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);
  --color-primary: var(--primary);
  --color-primary-soft: var(--primary-soft);
  --color-on-primary: var(--on-primary);
  --color-danger: var(--danger);
  --color-warn: var(--warn);
  --color-warn-soft: var(--warn-soft);
  --color-compose: var(--compose);

  --animate-toast: toast 200ms ease-out;
  @keyframes toast {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: none;
    }
  }
}

:root {
  --app: #f6f8fc;
  --surface: #ffffff;
  --surface-2: #f1f3f4;
  --hover: rgba(60, 64, 67, 0.08);
  --selected: #c2e7ff;
  --line: #e0e3e7;
  --ink: #1f1f1f;
  --ink-2: #444746;
  --ink-3: #5f6368;
  --primary: #0b57d0;
  --primary-soft: #d3e3fd;
  --on-primary: #ffffff;
  --danger: #b3261e;
  --warn: #5a4300;
  --warn-soft: #feefc3;
  --compose: #c2e7ff;
  color-scheme: light;
}

.dark {
  --app: #161718;
  --surface: #202124;
  --surface-2: #2d2e31;
  --hover: rgba(232, 234, 237, 0.08);
  --selected: #004a77;
  --line: #3c4043;
  --ink: #e8eaed;
  --ink-2: #c4c7c5;
  --ink-3: #9aa0a6;
  --primary: #a8c7fa;
  --primary-soft: #2b4a70;
  --on-primary: #062e6f;
  --danger: #f2b8b5;
  --warn: #fdd663;
  --warn-soft: #4a3b12;
  --compose: #3c4043;
  color-scheme: dark;
}

@layer base {
  html,
  body,
  #root {
    height: 100%;
  }

  body {
    margin: 0;
    background: var(--app);
    color: var(--ink);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }

  :focus-visible {
    outline: 2px solid var(--primary);
    outline-offset: 2px;
  }

  button:not(:disabled),
  [role="button"],
  [role="row"],
  label:has(> input[type="checkbox"]) {
    cursor: pointer;
  }
}

/* Rendered mail and compose body. Sanitized HTML from lib/sanitize.ts only. */
.mail-html {
  overflow-wrap: anywhere;
}

.mail-html p {
  margin: 0 0 0.75em;
}

.mail-html a {
  color: var(--primary);
  text-decoration: underline;
}

.mail-html blockquote {
  margin: 0.5em 0;
  padding-left: 12px;
  border-left: 2px solid var(--line);
  color: var(--ink-3);
}

.mail-html ul {
  list-style: disc;
  margin: 0 0 0.75em;
  padding-left: 1.5em;
}

.mail-html ol {
  list-style: decimal;
  margin: 0 0 0.75em;
  padding-left: 1.5em;
}

.mail-html h1,
.mail-html h2,
.mail-html h3,
.mail-html h4 {
  margin: 0.8em 0 0.4em;
  font-weight: 500;
  line-height: 1.3;
}

.mail-html code {
  padding: 0 4px;
  border-radius: 4px;
  background: var(--surface-2);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.9em;
}

.mail-html pre {
  overflow-x: auto;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--surface-2);
}

.mail-html details {
  margin: 0.5em 0;
}

.mail-html summary {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--ink-3);
  font-size: 12px;
  cursor: pointer;
  list-style: none;
  user-select: none;
}

.mail-html summary::-webkit-details-marker {
  display: none;
}

.mail-html details[open] > summary {
  margin-bottom: 8px;
}

.compose-editor:empty::before {
  content: attr(data-placeholder);
  color: var(--ink-3);
  pointer-events: none;
}

/* Quiet scrollbars so list and reading panes feel like a web app. */
* {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklab, var(--ink-3) 35%, transparent) transparent;
}

